package org.marketreview.nativeapp;
import android.content.Context;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.File;
import java.util.*;
import org.json.*;
final class FuturesMonitorScreen extends LinearLayout {
 interface Refresh{void start(String token,List<String> symbols)throws Exception;}
 interface Cancel{void stop(String token)throws Exception;}
 interface Work{void run()throws Exception;}
 final FuturesMonitorStore store;final Refresh refreshHost;final Cancel cancelHost;
 final Handler handler=new Handler(Looper.getMainLooper());
 final FrameLayout frame;final ScrollView main,detail,raw;final LinearLayout histories,points;final TextView status,summary,reader,pages;
 final Button refresh,stop;final Spinner symbol;final Map<String,CheckBox> choices=new LinkedHashMap<>();
 String activeToken="",historySymbol="IF0";List<String> requested=Collections.emptyList();
 JSONObject captured=new JSONObject();int historyPage=0,pointPage=0,view=0,readerIndex=-1;boolean closed=false,dark=false,loading=false;
 void safe(Work w){try{w.run();}catch(Exception e){status.setText(e.getMessage());}}
 static LinearLayout layout(ScrollView scroll){LinearLayout l=new LinearLayout(scroll.getContext());l.setOrientation(VERTICAL);scroll.addView(l);return l;}
 TextView text(LinearLayout l,String value){TextView t=new TextView(getContext());t.setText(value);t.setTextIsSelectable(true);l.addView(t);return t;}
 Button button(LinearLayout l,String title,Work w){Button b=new Button(getContext());b.setText(title);l.addView(b);b.setOnClickListener(v->safe(w));return b;}
 FuturesMonitorScreen(Context c,File file,Refresh refreshHost,Cancel cancelHost)throws Exception{
  super(c);this.store=new FuturesMonitorStore(file);this.refreshHost=refreshHost;this.cancelHost=cancelHost;setOrientation(VERTICAL);
  TextView title=new TextView(c);title.setText("股指期货一分钟价量仓 · 主力连续序列");addView(title);frame=new FrameLayout(c);addView(frame,new LayoutParams(-1,0,1));status=new TextView(c);status.setTag("futuresStatus");addView(status);
  main=new ScrollView(c);LinearLayout m=layout(main);text(m,"IF0/IH0/IC0/IM0 为连续序列，实际到期合约未知。价格与持仓变化不代表净多净空。仅手动刷新，实时性未保证。");
  JSONArray catalog=FuturesMonitorModel.catalog();List<String> symbols=new ArrayList<>();for(int i=0;i<catalog.length();i++){JSONObject item=catalog.getJSONObject(i);String s=item.getString("symbol");symbols.add(s);CheckBox check=new CheckBox(c);check.setText(s+" · "+item.getString("name"));check.setChecked(s.equals("IF0"));check.setTag("futuresChoice"+s);m.addView(check);choices.put(s,check);}
  refresh=button(m,"刷新勾选序列",this::start);refresh.setTag("futuresRefresh");stop=button(m,"取消本次刷新",this::cancel);stop.setTag("futuresCancel");
  symbol=new Spinner(c);symbol.setTag("futuresHistorySymbol");symbol.setAdapter(new ArrayAdapter<>(c,android.R.layout.simple_spinner_dropdown_item,symbols));m.addView(symbol);symbol.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?>p){}public void onItemSelected(AdapterView<?>p,View v,int index,long id){if(!loading&&!closed&&index==symbol.getSelectedItemPosition()&&index>=0&&index<symbols.size()&&!historySymbol.equals(symbols.get(index))){historySymbol=symbols.get(index);historyPage=0;safe(()->load());}}});
  text(m,"本机成功响应历史 · 时效未验证的旧缓存");histories=new LinearLayout(c);histories.setOrientation(VERTICAL);histories.setTag("futuresHistory");m.addView(histories);button(m,"历史上一页",()->{if(historyPage>0)historyPage--;load();});button(m,"历史下一页",()->{if(store.history(historySymbol,(historyPage+1)*20,20).length()>0){historyPage++;load();}});button(m,"重读本机历史",this::load);
  reader=new TextView(c);reader.setTag("futuresReader");reader.setTextIsSelectable(true);detail=new ScrollView(c);LinearLayout d=layout(detail);button(d,"返回本机历史",()->show(0));summary=text(d,"");summary.setTag("futuresSummary");points=new LinearLayout(c);points.setOrientation(VERTICAL);points.setTag("futuresPoints");d.addView(points);pages=text(d,"");button(d,"点上一页",()->{if(pointPage>0)pointPage--;showPoints();});button(d,"点下一页",()->{if((pointPage+1)*20<captured.getJSONArray("rows").length())pointPage++;showPoints();});button(d,"完整响应 / 排除原因 / 来源详情",()->openReader(-1));
  raw=new ScrollView(c);LinearLayout r=layout(raw);button(r,"返回价量仓明细",()->show(1));r.addView(reader);setBusy(false);show(0);safe(this::load);
 }
 void setBusy(boolean busy){refresh.setEnabled(!closed&&!busy&&refreshHost!=null);stop.setEnabled(!closed&&busy);for(CheckBox c:choices.values())c.setEnabled(!closed&&!busy);}
 void show(int page){view=page;frame.removeAllViews();frame.addView(page==2?raw:page==1?detail:main,new FrameLayout.LayoutParams(-1,-1));setDarkTheme(dark);}
 void setDarkTheme(boolean value){dark=value;SourceHandoffPanel.styleTree(this,value);}
 void load()throws Exception{JSONArray rows=store.history(historySymbol,historyPage*20,20);histories.removeAllViews();for(int i=0;i<rows.length();i++){JSONObject item=rows.getJSONObject(i);button(histories,item.getString("observedAt")+" · 接收 "+item.getString("receivedAt")+" · 本机旧缓存",()->openSnapshot(item.getString("id")));}status.setText("本机历史第"+(historyPage+1)+"页 · "+rows.length()+"条 · 时效未验证；失败/取消保留成功历史");setDarkTheme(dark);}
 void start()throws Exception{FuturesMonitorModel.require(!closed&&activeToken.isEmpty(),"已有刷新未完成或页面关闭");FuturesMonitorModel.require(refreshHost!=null,"宿主未连接刷新入口");List<String> selected=new ArrayList<>();for(Map.Entry<String,CheckBox> e:choices.entrySet())if(e.getValue().isChecked())selected.add(e.getKey());FuturesMonitorModel.require(selected.size()>=1&&selected.size()<=4,"请选择1至4个目录序列");activeToken=UUID.randomUUID().toString();requested=Collections.unmodifiableList(new ArrayList<>(selected));setBusy(true);status.setText("等待宿主返回选定序列的实际来源响应…");try{refreshHost.start(activeToken,requested);}catch(Exception e){activeToken="";requested=Collections.emptyList();setBusy(false);throw e;}}
 void cancel(){if(activeToken.isEmpty())return;String revoked=activeToken;activeToken="";requested=Collections.emptyList();setBusy(false);status.setText("本次刷新已取消；成功历史保留");if(cancelHost!=null)try{cancelHost.stop(revoked);}catch(Exception e){if(!closed)status.setText("本次令牌已撤销；宿主取消报告异常");}}
 void close(){closed=true;cancel();setBusy(false);}
 void deliver(String token,JSONArray responses,String error){
  // Copy host data before posting; no retained mutable response array/Activity callback.
  String data=responses==null?"[]":responses.toString();handler.post(()->{if(closed||activeToken.isEmpty()||!activeToken.equals(token))return;List<String> expected=requested;activeToken="";requested=Collections.emptyList();setBusy(false);if(error!=null&&!error.isEmpty()){status.setText("刷新失败："+error+"；成功历史保留");return;}safe(()->{
   JSONArray batch=new JSONArray(data);FuturesMonitorModel.require(batch.length()<=4,"宿主响应批次超过选定范围");Set<String> seen=new HashSet<>();List<JSONObject> parsed=new ArrayList<>();List<String> failures=new ArrayList<>();for(int i=0;i<batch.length();i++){JSONObject o=batch.getJSONObject(i);String s=o.getString("symbol");FuturesMonitorModel.require(expected.contains(s)&&seen.add(s),"宿主返回非请求或重复序列");FuturesMonitorModel.require(o.opt("payload") instanceof String&&o.opt("receivedAt") instanceof String&&FuturesMonitorModel.sourceUrl(s).equals(o.opt("sourceUrl")),"响应来源绑定/文本无效");JSONObject p=FuturesMonitorModel.parse(s,o.getString("payload"),o.getString("receivedAt"));if("available".equals(p.getString("availability")))parsed.add(p);else failures.add(s+" 缺数/解析不可用");}for(String s:expected)if(!seen.contains(s))failures.add(s+" 未返回");for(JSONObject p:parsed)store.save(p);historyPage=0;load();status.setText("本次成功保存"+parsed.size()+"个来源响应；实时性未保证"+(failures.isEmpty()?"":" · "+String.join("；",failures)));
  });});
 }
 void openSnapshot(String id)throws Exception{captured=store.read(id);pointPage=0;showPoints();show(1);}
 static String positioning(String s){if(s.equals("price-up-oi-up"))return "价格上升 / 持仓增加";if(s.equals("price-up-oi-down"))return "价格上升 / 持仓减少";if(s.equals("price-down-oi-up"))return "价格下降 / 持仓增加";if(s.equals("price-down-oi-down"))return "价格下降 / 持仓减少";return "相邻一分钟变化不可用";}
 static String value(JSONObject o,String key){return o.isNull(key)||!o.has(key)?"不可用":String.valueOf(o.opt(key));}
 void showPoints()throws Exception{JSONObject s=captured.getJSONObject("summary");summary.setText(captured.getString("instrumentId")+" · 本机旧缓存，时效未验证\n来源日期 "+value(captured,"sourceDate")+" · 交易日未知 · 实际到期合约未知\n来源时点 "+value(s,"observedAt")+" · 接收 "+value(captured,"receivedAt")+"\n价格 "+value(s,"price")+" · 成交 "+value(s,"minuteVolume")+"手 · 持仓 "+value(s,"openInterest")+"手\n相邻1分价格变化 "+value(s,"minutePriceChange")+"点 · 持仓变化 "+value(s,"openInterestChange")+"手\n"+positioning(s.getString("positioningState"))+"（零变化按旧规则归入非负侧；非净多净空）\n加载窗口涨跌 "+value(s,"sessionChangePct")+"% · "+s.getString("baselineLabel")+"\n"+(captured.isNull("reason")?"":value(captured,"reason")));JSONArray rows=captured.getJSONArray("rows");pointPage=Math.max(0,Math.min(pointPage,Math.max(0,(rows.length()-1)/20)));points.removeAllViews();for(int i=pointPage*20;i<Math.min(rows.length(),(pointPage+1)*20);i++){int index=i;JSONObject p=rows.getJSONObject(i);button(points,p.getString("time")+" · 价 "+value(p,"price")+" · 成交 "+value(p,"volume")+" · 持仓 "+value(p,"openInterest"),()->openReader(index));}pages.setText("点第"+(pointPage+1)+"页 · 共"+rows.length()+"点；选择记录查看原始字段");setDarkTheme(dark);}
 void openReader(int index)throws Exception{readerIndex=index;JSONObject full=captured;if(index>=0){JSONObject row=captured.getJSONArray("rows").getJSONObject(index);full=new JSONObject().put("derived",row).put("audit",captured.getJSONArray("audit").get(row.getInt("sourceIndex")));}reader.setText(full.toString(2));raw.scrollTo(0,0);show(2);}
 boolean back(){if(view==0)return false;show(view==2?1:0);return true;}
 JSONObject saveState()throws Exception{JSONArray selected=new JSONArray();for(Map.Entry<String,CheckBox> e:choices.entrySet())if(e.getValue().isChecked())selected.put(e.getKey());return new JSONObject().put("selected",selected).put("symbol",historySymbol).put("historyPage",historyPage).put("pointPage",pointPage).put("view",view).put("snapshotId",captured.opt("id")==null?JSONObject.NULL:captured.opt("id")).put("readerIndex",readerIndex).put("mainScroll",main.getScrollY()).put("detailScroll",detail.getScrollY()).put("rawScroll",raw.getScrollY());}
 void restoreState(JSONObject input)throws Exception{cancel();JSONObject s=new JSONObject(input.toString());String sym=s.optString("symbol","IF0");FuturesMonitorModel.sourceUrl(sym);historySymbol=sym;loading=true;try{int index=new ArrayList<>(choices.keySet()).indexOf(sym);symbol.setSelection(index);JSONArray selected=s.optJSONArray("selected");Set<String> chosen=new HashSet<>();if(selected!=null)for(int i=0;i<selected.length();i++)chosen.add(selected.getString(i));for(Map.Entry<String,CheckBox> e:choices.entrySet())e.getValue().setChecked(chosen.contains(e.getKey()));historyPage=Math.max(0,Math.min(1000000,s.optInt("historyPage")));load();int target=s.optInt("view");if(target>0&&!s.isNull("snapshotId")){openSnapshot(s.getString("snapshotId"));pointPage=s.optInt("pointPage");showPoints();if(target==2)openReader(s.optInt("readerIndex",-1));}else show(0);}finally{loading=false;}main.post(()->main.scrollTo(0,s.optInt("mainScroll")));detail.post(()->detail.scrollTo(0,s.optInt("detailScroll")));raw.post(()->raw.scrollTo(0,s.optInt("rawScroll")));}
}

